SELECT DATE_FORMAT(sf.order_date,'%Y-%m') AS `月份`, COALESCE(SUM(sf.amount),0) AS `销售额` FROM sales_dw.dws_off_offline_sale_dfn sf WHERE sf.order_date >= '1000-01-01' AND sf.order_date < '9999-12-31' GROUP BY DATE_FORMAT(sf.order_date,'%Y-%m') ORDER BY DATE_FORMAT(sf.order_date,'%Y-%m') ASC LIMIT 200
